using System;
using Unity.Collections;
using UnityEngine.TextCore.Text;

namespace UnityEngine.UIElements
{
    /// <summary>Drawing of a text element: its text generated by TextCore (glyph quads in the
    /// content rect) and, over it, the selection highlight or the caret; plus eliding of text that
    /// overflows, as Unity's TextElement does through its text job system.</summary>
    public partial class TextElement
    {
        bool m_WasElided;

        internal static void OnGenerateVisualContent(MeshGenerationContext mgc)
        {
            if (!(mgc.visualElement is TextElement textElement)) return;
            textElement.UpdateVisibleText();
            if (!UITKTextHandle.IsFontAssigned(textElement)) return;
            textElement.UaGenerateText(mgc);
        }

        /// <summary>Prepares the font, loads the glyphs the text needs into the atlas, generates the
        /// text and draws its glyph quads (one draw per font material).</summary>
        void UaGenerateText(MeshGenerationContext mgc)
        {
            var handle = uitkTextHandle;
            var textSettings = UITKTextHandle.GetTextSettingsFrom(this);
            textSettings?.lineBreakingRules?.LoadLineBreakingRules();
            if (handle.ConvertUssToTextGenerationSettings()) handle.PrepareFontAsset();
            FontAsset.UpdateFontAssetsInUpdateQueue();
            handle.UpdateMesh();
            var textInfo = handle.textInfo;
            if (textInfo?.meshInfo != null)
            {
                var offset = contentRect.min;
                for (int i = 0; i < textInfo.meshInfo.Length; i++) DrawMeshInfo(mgc, textInfo.meshInfo[i], offset);
            }
            OnGenerateTextOver(mgc);
        }

        static void DrawMeshInfo(MeshGenerationContext mgc, MeshInfo meshInfo, Vector2 offset)
        {
            int count = meshInfo.vertexCount & ~3;
            if (count == 0 || meshInfo.vertexData == null) return;
            var material = meshInfo.material;
            var atlas = material != null ? material.mainTexture as Texture2D : null;
            if (atlas == null) return;
            float sdfScale = 0f;
            if (!TextGeneratorUtilities.IsBitmapRendering(meshInfo.glyphRenderMode) && atlas.format == TextureFormat.Alpha8)
                sdfScale = material.GetFloat(TextShaderUtilities.ID_GradientScale);
            var vertices = new NativeArray<Vertex>(count, Allocator.Temp);
            try
            {
                for (int v = 0; v < count; v++) vertices[v] = ToUIRVertex(meshInfo.vertexData[v], offset);
                mgc.UaDrawText(new NativeSlice<Vertex>(vertices), atlas, sdfScale);
            }
            finally
            {
                vertices.Dispose();
            }
        }

        /// <summary>A TextCore vertex as a UI vertex: moved into the content rect; a negative uv2.y marks bold glyphs (extra dilation).</summary>
        static Vertex ToUIRVertex(TextCoreVertex vertex, Vector2 offset) => new Vertex
        {
            position = new Vector3(vertex.position.x + offset.x, vertex.position.y + offset.y, 0f),
            uv = new Vector2(vertex.uv0.x, vertex.uv0.y),
            tint = vertex.color,
            flags = new Color32(0, (byte)(vertex.uv2.y < 0f ? 255 : 0), 0, 0),
        };

        /// <summary>After the text: the selection highlight of a focused element, else the caret of an
        /// editable one; then the elided state the generator reached.</summary>
        internal void OnGenerateTextOver(MeshGenerationContext mgc)
        {
            if (selection.HasSelection() && hasFocus)
                DrawHighlighting(mgc);
            else if (!edition.isReadOnly && selection.isSelectable && uaSelecting.selecting.revealCursor)
                DrawCaret(mgc);
            if (ShouldElide() && uitkTextHandle.TextLibraryCanElide()) isElided = uitkTextHandle.IsElided();
            UpdateTooltip();
        }

        void DrawHighlighting(MeshGenerationContext mgc)
        {
            var handle = uitkTextHandle;
            int start = Math.Min(selection.cursorIndex, selection.selectIndex);
            int end = Math.Max(selection.cursorIndex, selection.selectIndex);
            var from = handle.GetCursorPositionFromStringIndexUsingLineHeight(start);
            var to = handle.GetCursorPositionFromStringIndexUsingLineHeight(end);
            int firstLine = handle.GetLineNumber(start);
            int lastLine = handle.GetLineNumber(end);
            float lineHeight = handle.GetLineHeight(firstLine);
            var min = contentRect.min;
            if (firstLine == lastLine)
            {
                mgc.UaDrawSolidRect(new Rect(from.x + min.x, from.y + min.y - lineHeight, to.x - from.x, lineHeight), selectionColor);
                return;
            }
            var lines = handle.textInfo.lineInfo;
            for (int line = firstLine; line <= lastLine; line++)
            {
                // A line's highlight: from the selection start (or the line's first character) to the
                // selection end (or past the line's last character).
                if (line == firstLine)
                {
                    to = handle.GetCursorPositionFromStringIndexUsingLineHeight(LastCharacterOfLine(line), useXAdvance: true);
                }
                else if (line == lastLine)
                {
                    from = handle.GetCursorPositionFromStringIndexUsingLineHeight(lines[line].firstCharacterIndex);
                    to = handle.GetCursorPositionFromStringIndexUsingLineHeight(end, useXAdvance: true);
                }
                else
                {
                    from = handle.GetCursorPositionFromStringIndexUsingLineHeight(lines[line].firstCharacterIndex);
                    to = handle.GetCursorPositionFromStringIndexUsingLineHeight(LastCharacterOfLine(line), useXAdvance: true);
                }
                mgc.UaDrawSolidRect(new Rect(from.x + min.x, from.y + min.y - lineHeight, to.x - from.x, lineHeight), selectionColor);
            }
        }

        internal void DrawCaret(MeshGenerationContext mgc)
        {
            float height = uitkTextHandle.GetCharacterHeightFromIndex(selection.cursorIndex);
            float width = Unbound.UIElements.UaLayout.CeilToPixelGrid(selection.cursorWidth, scaledPixelsPerPoint, 0f);
            var position = selection.cursorPosition;
            mgc.UaDrawSolidRect(new Rect(position.x, position.y - height, width, height), cursorColor);
        }

        /// <summary>The line's last character, not counting the line breaks that end it.</summary>
        int LastCharacterOfLine(int line)
        {
            var textInfo = uitkTextHandle.textInfo;
            int index = textInfo.lineInfo[line].lastCharacterIndex;
            int first = textInfo.lineInfo[line].firstCharacterIndex;
            while (index > first)
            {
                uint c = textInfo.textElementInfo[index].character;
                if (c != '\n' && c != '\r') break;
                index--;
            }
            return index;
        }

        bool ShouldElide() => computedValues.textOverflow == TextOverflow.Ellipsis && computedValues.overflow == OverflowInternal.Hidden;

        /// <summary>The elided text for overflow positions the generator can't elide itself (start and
        /// middle); with the end position the generator elides while generating.</summary>
        void UpdateVisibleText()
        {
            bool elide = ShouldElide();
            if (elide && uitkTextHandle.TextLibraryCanElide()) return;
            if (!elide)
            {
                isElided = false;
                return;
            }
            elidedText = ElideText(text, k_EllipsisText, contentRect.width, computedValues.unityTextOverflowPosition);
            isElided = !string.Equals(elidedText, text, StringComparison.Ordinal);
        }

        /// <summary>The longest variant of the text with the ellipsis at the overflow position that
        /// fits the width, found by bisecting how many characters to keep (Unity's ElideText).</summary>
        internal string ElideText(string drawText, string ellipsisText, float width, TextOverflowPosition position)
        {
            float paddingRight = resolvedStyle.paddingRight;
            if (float.IsNaN(paddingRight)) paddingRight = 0f;
            float tolerance = Mathf.Clamp(paddingRight, 1f / scaledPixelsPerPoint, 1f);
            float Width(string s) => MeasureTextSize(s, 0f, MeasureMode.Undefined, 0f, MeasureMode.Undefined).x;
            if (Width(drawText) <= width + tolerance || string.IsNullOrEmpty(ellipsisText)) return drawText;
            string shortest = drawText.Length > 1 ? ellipsisText : drawText;
            if (Width(shortest) >= width) return shortest;

            int last = drawText.Length - 1;
            int fitting = -1;
            string candidate = drawText;
            int low = position == TextOverflowPosition.Start ? 1 : 0;
            int high = position == TextOverflowPosition.Start || position == TextOverflowPosition.Middle ? last : last - 1;
            for (int mid = (low + high) / 2; low <= high; mid = (low + high) / 2)
            {
                candidate = Candidate(drawText, ellipsisText, position, mid, last);
                float w = Width(candidate);
                if (Math.Abs(w - width) < 1e-30f) return candidate;
                if (position == TextOverflowPosition.Start)
                {
                    // Keeping the characters from mid on: fewer kept as mid grows.
                    if (w > width)
                    {
                        if (fitting == mid - 1) return ellipsisText + drawText.Substring(fitting, last - (fitting - 1));
                        low = mid + 1;
                    }
                    else
                    {
                        high = mid - 1;
                        fitting = mid;
                    }
                    continue;
                }
                if (w > width)
                {
                    if (fitting == mid - 1)
                    {
                        if (position == TextOverflowPosition.End) return drawText.Substring(0, fitting) + ellipsisText;
                        int side = Mathf.Max(fitting - 1, 0);
                        return drawText.Substring(0, side) + ellipsisText + drawText.Substring(last - side);
                    }
                    high = mid - 1;
                }
                else
                {
                    low = mid + 1;
                    fitting = mid;
                }
            }
            return candidate;
        }

        static string Candidate(string text, string ellipsis, TextOverflowPosition position, int mid, int last)
        {
            switch (position)
            {
                case TextOverflowPosition.Start:
                    return ellipsis + text.Substring(mid, last - (mid - 1));
                case TextOverflowPosition.Middle:
                    string head = mid - 1 <= 0 ? string.Empty : text.Substring(0, mid - 1);
                    string tail = last - (mid - 1) <= 0 ? string.Empty : text.Substring(last - (mid - 1));
                    return head + ellipsis + tail;
                default:
                    return text.Substring(0, mid) + ellipsis;
            }
        }

        void UpdateTooltip()
        {
            if (displayTooltipWhenElided && isElided)
            {
                tooltip = text;
                m_WasElided = true;
            }
            else if (m_WasElided)
            {
                tooltip = null;
                m_WasElided = false;
            }
        }
    }
}
